export function getQuestion(topicId, usedIds = []) {
  const bank = QUESTION_BANK[topicId] || []
  const available = bank.filter((_, i) => !usedIds.includes(i))
  if (!available.length) return null
  const pool = available
  const item = pool[Math.floor(Math.random() * pool.length)]
  const idx = bank.indexOf(item)
  return { ...item, question: item.q, answer: item.a, hint: item.h, fact: item.f, _idx: idx }
}

export function getBankSize(topicId) {
  return (QUESTION_BANK[topicId] || []).length
}
